fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    if n < 2 {
        // If there are fewer than 2 elements, no delimiters needed.
        return numbers;
    }

    // The resulting length is 2*n - 1.
    let mut result = Vec::with_capacity(2 * n - 1);

    // Push the first element.
    result.push(numbers[0]);

    // For each subsequent element, push the delimiter then the element.
    for &num in &numbers[1..] {
        result.push(delimiter);
        result.push(num);
    }

    result
}

